<script setup>
import { computed, ref } from 'vue';
import { decodeSellerPageData } from '../utils/sellerPageData';
const props=defineProps({pageData:{type:String,default:''}});const d=decodeSellerPageData(props.pageData);
const search=ref(d.filters.search||'');const orderStatus=ref(d.filters.order_status||'');const paymentStatus=ref(d.filters.payment_status||'');const selected=ref(null);const showDelete=ref(false);const deleting=ref(false);const hasFilters=computed(()=>!!(search.value||orderStatus.value||paymentStatus.value));
function askDelete(order){selected.value=order;showDelete.value=true;}function closeDelete(){showDelete.value=false;selected.value=null;}
async function deleteOrder(){if(!selected.value||deleting.value)return;deleting.value=true;try{const response=await fetch(selected.value.deleteUrl,{method:'POST',headers:{'X-CSRF-TOKEN':d.csrfToken,Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({_method:'DELETE'}),credentials:'same-origin'});const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Unable to delete the order.');closeDelete();if(window.Swal){await window.Swal.fire({toast:true,position:'top-end',icon:'success',title:result.message,showConfirmButton:false,timer:1800});}else{window.alert(result.message);}window.location.assign(window.location.href);}catch(error){if(window.Swal){window.Swal.fire({icon:'error',title:'Unable to delete order',text:error.message});}else{window.alert(error.message);}}finally{deleting.value=false;}}
</script>
<template><div class="seller-orders-page">
    <div class="seller-page-heading"><div><h2>Orders</h2><p>Manage orders for your books</p></div></div>
    <div class="seller-orders-stats"><div v-for="stat in d.stats" :key="stat.label" class="seller-order-stat-card"><div class="seller-order-stat-icon" :class="stat.type"><i class="bi" :class="stat.icon"></i></div><div><span>{{ stat.label }}</span><strong>{{ stat.value }}</strong></div></div></div>
    <div class="seller-orders-filter-card"><form :action="d.indexUrl" method="GET" class="seller-orders-filter-form"><div class="seller-order-search"><div class="seller-order-search-input"><i class="bi bi-search"></i><input v-model="search" type="text" name="search" placeholder="Search order, customer or book..."></div><button type="submit" class="seller-order-search-button"><i class="bi bi-search"></i><span>Search</span></button></div><div class="seller-order-filter-select"><label for="order_status">Order Status</label><select id="order_status" name="order_status" v-model="orderStatus"><option value="">All Statuses</option><option v-for="s in d.orderStatuses" :key="s" :value="s">{{ s[0].toUpperCase()+s.slice(1) }}</option></select></div><div class="seller-order-filter-select"><label for="payment_status">Payment Status</label><select id="payment_status" name="payment_status" v-model="paymentStatus"><option value="">All Payments</option><option v-for="s in d.paymentStatuses" :key="s" :value="s">{{ s[0].toUpperCase()+s.slice(1) }}</option></select></div><button type="submit" class="seller-order-filter-button"><i class="bi bi-funnel"></i><span>Filter</span></button><a v-if="hasFilters" :href="d.indexUrl" class="seller-order-reset-button"><i class="bi bi-arrow-counterclockwise"></i><span>Reset</span></a></form></div>
    <div id="sellerOrdersContent"><div class="seller-orders-card"><div class="seller-orders-card-header"><div class="seller-orders-card-title"><div class="seller-orders-card-icon"><i class="bi bi-bag-check"></i></div><div><h5>Recent Orders</h5><p>{{ d.pagination.total }} {{ d.pagination.total===1?'order':'orders' }} found</p></div></div></div>
        <div v-if="d.orders.length" class="seller-orders-table-wrapper"><table class="seller-orders-table"><thead><tr><th>Order</th><th>Book</th><th>Customer</th><th>Qty</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th><th>Action</th></tr></thead><tbody><tr v-for="order in d.orders" :key="order.id"><td><div class="seller-order-number"><span>#{{ order.number }}</span></div></td><td><div class="seller-order-book"><div class="seller-order-book-cover"><img v-if="order.coverUrl" :src="order.coverUrl" :alt="order.bookTitle"><div v-else class="seller-order-no-cover"><i class="bi bi-book"></i></div></div><div class="seller-order-book-info"><strong>{{ order.bookTitle }}</strong><span v-if="order.isbn">ISBN: {{ order.isbn }}</span></div></div></td><td><div class="seller-order-customer"><div class="seller-order-customer-avatar"><img v-if="order.photoUrl" :src="order.photoUrl" :alt="order.customer"><span v-else>{{ order.initial }}</span></div><div class="seller-order-customer-info"><strong>{{ order.customer }}</strong><span v-if="order.email">{{ order.email }}</span></div></div></td><td><span class="seller-order-quantity">{{ order.quantity }}</span></td><td><strong class="seller-order-total">${{ order.total }}</strong></td><td><span class="seller-payment-badge" :class="order.paymentClass"><i></i>{{ order.paymentLabel }}</span></td><td><span class="seller-order-status-badge" :class="order.statusClass"><i></i>{{ order.statusLabel }}</span></td><td><div class="seller-order-date"><strong>{{ order.date }}</strong><span>{{ order.time }}</span></div></td><td><div class="seller-order-actions"><a :href="order.showUrl" class="seller-order-view-button" title="View Order"><i class="bi bi-eye"></i></a><button v-if="order.canDelete" type="button" class="seller-order-delete-button" title="Delete Order" @click="askDelete(order)"><i class="bi bi-trash"></i></button></div></td></tr></tbody></table></div>
        <div v-if="d.orders.length && d.pagination.links.length>3" class="seller-orders-pagination"><nav aria-label="Pagination"><a v-for="(link,index) in d.pagination.links" :key="index" :href="link.url||undefined" :class="{active:link.active,disabled:!link.url}" v-html="link.label"></a></nav></div>
        <div v-if="!d.orders.length" class="seller-orders-empty"><div class="seller-orders-empty-icon"><i class="bi bi-bag-x"></i></div><h4>No orders found</h4><p>{{ hasFilters?'No orders match your current filters.':"You don't have any orders for your books yet." }}</p><a v-if="hasFilters" :href="d.indexUrl" class="seller-order-empty-button"><i class="bi bi-arrow-counterclockwise"></i><span>Clear Filters</span></a></div>
    </div></div>
    <div class="seller-modal-overlay" :class="{show:showDelete}" @click.self="closeDelete"><div class="seller-delete-modal" role="dialog" aria-modal="true"><button type="button" class="seller-modal-close" aria-label="Close" @click="closeDelete"><i class="bi bi-x-lg"></i></button><div class="seller-delete-icon"><i class="bi bi-trash3"></i></div><h4>Delete Order?</h4><p>Are you sure you want to delete order <strong>#{{ selected?.number }}</strong>?<br>This action cannot be undone.</p><div class="seller-delete-actions"><button type="button" class="seller-modal-cancel" @click="closeDelete">Cancel</button><button type="button" class="seller-modal-delete" :disabled="deleting" @click="deleteOrder"><i class="bi bi-trash3"></i><span>{{ deleting?'Deleting...':'Delete Order' }}</span></button></div></div></div>
</div></template>
